return {
    ["Word Pyramid"] = { fr = "La Pyramide des mots", es = "La pirámide de palabras", de = "Wörterpyramide" },
    ["Word-guessing party game for four, two teams of two, inspired by the classic French TV word game: one-word clues that cost bricks, riddles, ping-pong, against the clock, proper names, then the Great Pyramid final."] = { fr = "Jeu de mots à faire deviner pour quatre, en deux équipes de deux, inspiré du jeu télévisé français classique : des indices d'un seul mot qui coûtent des briques, les énigmes, le ping-pong, le contre-la-montre, les noms propres, puis la finale de la Grande Pyramide.", es = "Juego de adivinar palabras para cuatro, dos equipos de dos, inspirado en el clásico concurso francés de televisión: pistas de una sola palabra que cuestan ladrillos, enigmas, ping-pong, contrarreloj, nombres propios y la final de la Gran Pirámide.", de = "Worträtsel-Partyspiel für vier, zwei Zweierteams, nach dem Vorbild der klassischen französischen TV-Rateshow: Hinweise aus einem Wort, die Steine kosten, Rätsel, Ping-Pong, gegen die Uhr, Eigennamen, dann das Finale der Großen Pyramide." },
    ["%1 brick"] = { fr = "%1 brique", es = "%1 ladrillo", de = "%1 Stein" },
    ["%1 bricks"] = { fr = "%1 briques", es = "%1 ladrillos", de = "%1 Steine" },
    ["%1, do you bid?"] = { fr = "%1, une annonce ?", es = "%1, ¿pujáis?", de = "%1, bietet ihr?" },
    ["%1, pick a riddle"] = { fr = "%1, choisissez une énigme", es = "%1, elegid un enigma", de = "%1, wählt ein Rätsel" },
    ["%1, pick a theme for 30 seconds"] = { fr = "%1, choisissez un thème pour 30 secondes", es = "%1, elegid un tema para 30 segundos", de = "%1, wählt ein Thema für 30 Sekunden" },
    ["%1, pick a theme of 4 names"] = { fr = "%1, choisissez un thème de 4 noms", es = "%1, elegid un tema de 4 nombres", de = "%1, wählt ein Thema mit 4 Namen" },
    ["30 seconds, up to 7 words."] = { fr = "30 secondes, jusqu'à 7 mots.", es = "30 segundos, hasta 7 palabras.", de = "30 Sekunden, bis zu 7 Wörter." },
    ["4 themes, 2 per team, the team behind picks first. 30 seconds to find up to 7 words linked to the theme, 1 point each."] = { fr = "4 thèmes, 2 par équipe, l'équipe menée choisit la première. 30 secondes pour faire trouver jusqu'à 7 mots liés au thème, 1 point chacun.", es = "4 temas, 2 por equipo; elige primero el equipo que va detrás. 30 segundos para acertar hasta 7 palabras ligadas al tema, 1 punto cada una.", de = "4 Themen, 2 pro Team, das zurückliegende Team wählt zuerst. 30 Sekunden, um bis zu 7 Wörter zum Thema erraten zu lassen, je 1 Punkt." },
    ["5 words played back and forth: one clue for one team, the next clue on the same word for the other. 13 bricks in all, 5 at most per word; the team that finds the word scores 1 point."] = { fr = "5 mots joués en alternance : un indice pour une équipe, l'indice suivant sur le même mot pour l'autre. 13 briques en tout, 5 au plus par mot ; l'équipe qui trouve le mot marque 1 point.", es = "5 palabras jugadas en alternancia: una pista para un equipo, la siguiente pista sobre la misma palabra para el otro. 13 ladrillos en total, 5 como mucho por palabra; el equipo que la acierta gana 1 punto.", de = "5 Wörter im Wechsel: ein Hinweis für ein Team, der nächste Hinweis zum selben Wort für das andere. 13 Steine insgesamt, höchstens 5 pro Wort; das Team, das das Wort errät, bekommt 1 Punkt." },
    ["6 expressions in 1 minute, word by word or as a whole. All or nothing: %1."] = { fr = "6 expressions en 1 minute, mot par mot ou en entier. Tout ou rien : %1.", es = "6 expresiones en 1 minuto, palabra a palabra o enteras. Todo o nada: %1.", de = "6 Redewendungen in 1 Minute, Wort für Wort oder ganz. Alles oder nichts: %1." },
    ["6 riddles are offered; team A picks one, then B, then A, then B. Find its 5 words with 13 bricks (1 point each), then the riddle's answer (+1). All 5 words found: +1 per unused brick."] = { fr = "6 énigmes sont proposées ; l'équipe A en choisit une, puis B, puis A, puis B. Trouvez ses 5 mots avec 13 briques (1 point chacun), puis la réponse de l'énigme (+1). Les 5 mots trouvés : +1 par brique restante.", es = "Se ofrecen 6 enigmas; el equipo A elige uno, luego B, luego A, luego B. Acertad sus 5 palabras con 13 ladrillos (1 punto cada una) y luego la respuesta del enigma (+1). Las 5 palabras acertadas: +1 por ladrillo sobrante.", de = "6 Rätsel stehen zur Wahl; Team A wählt eines, dann B, dann A, dann B. Findet seine 5 Wörter mit 13 Steinen (je 1 Punkt), dann die Lösung des Rätsels (+1). Alle 5 Wörter gefunden: +1 pro übrigem Stein." },
    ["A tie! One name decides who plays the final."] = { fr = "Égalité ! Un seul nom décide qui joue la finale.", es = "¡Empate! Un solo nombre decide quién juega la final.", de = "Gleichstand! Ein Name entscheidet, wer das Finale spielt." },
    ["A word was missed: no bonus."] = { fr = "Un mot a été manqué : pas de bonus.", es = "Se falló una palabra: sin bonificación.", de = "Ein Wort wurde verfehlt: kein Bonus." },
    ["A: +%1 · B: +%2"] = { fr = "A : +%1 · B : +%2", es = "A: +%1 · B: +%2", de = "A: +%1 · B: +%2" },
    ["Against the clock"] = { fr = "Le contre-la-montre", es = "Contrarreloj", de = "Gegen die Uhr" },
    ["Answer to the riddle:"] = { fr = "Réponse de l'énigme :", es = "Respuesta del enigma:", de = "Lösung des Rätsels:" },
    ["Bid: %1"] = { fr = "Annonce : %1", es = "Puja: %1", de = "Gebot: %1" },
    ["Bonus if solved or not: +%1"] = { fr = "Bonus, résolue ou non : +%1", es = "Bonificación, resuelto o no: +%1", de = "Bonus, gelöst oder nicht: +%1" },
    ["Brick bonus: %1"] = { fr = "Bonus de briques : %1", es = "Bonificación de ladrillos: %1", de = "Steinbonus: %1" },
    ["Both clue-givers see the word; the teams take turns, one clue each. %1 starts."] = { fr = "Les deux meneurs voient le mot ; les équipes jouent à tour de rôle, un indice chacune. %1 commence.", es = "Los dos que dan pistas ven la palabra; los equipos se turnan, una pista cada uno. Empieza %1.", de = "Beide Hinweisgeber sehen das Wort; die Teams wechseln sich ab, je ein Hinweis. %1 beginnt." },
    ["Bricks per name"] = { fr = "Briques par nom", es = "Ladrillos por nombre", de = "Steine pro Name" },
    ["Bricks per name: %1"] = { fr = "Briques par nom : %1", es = "Ladrillos por nombre: %1", de = "Steine pro Name: %1" },
    ["Bricks: %1"] = { fr = "Briques : %1", es = "Ladrillos: %1", de = "Steine: %1" },
    ["Bricks: %1/%2"] = { fr = "Briques : %1/%2", es = "Ladrillos: %1/%2", de = "Steine: %1/%2" },
    ["Clue given / Wrong"] = { fr = "Indice donné / Faux", es = "Pista dada / Fallo", de = "Hinweis gegeben / Falsch" },
    ["Continue"] = { fr = "Continuer", es = "Continuar", de = "Weiter" },
    ["Each team plays a theme of 4 famous names, %1 bricks at most per name. Before each name the other team may bid fewer bricks and take it over. Not found: the other team scores (2 points for a failed 1-brick bid). The leader then plays the final."] = { fr = "Chaque équipe joue un thème de 4 noms célèbres, %1 briques au plus par nom. Avant chaque nom, l'autre équipe peut annoncer moins de briques et le prendre. Non trouvé : l'autre équipe marque (2 points si une annonce à 1 brique échoue). L'équipe en tête joue ensuite la finale.", es = "Cada equipo juega un tema de 4 nombres célebres, %1 ladrillos como mucho por nombre. Antes de cada nombre, el otro equipo puede pujar menos ladrillos y quedárselo. Si no se acierta, puntúa el otro equipo (2 puntos si falla una puja de 1 ladrillo). El que va en cabeza juega luego la final.", de = "Jedes Team spielt ein Thema mit 4 berühmten Namen, höchstens %1 Steine pro Name. Vor jedem Namen darf das andere Team weniger Steine bieten und ihn übernehmen. Nicht erraten: das andere Team punktet (2 Punkte, wenn ein 1-Stein-Gebot scheitert). Das führende Team spielt dann das Finale." },
    ["Final score: A %1 · B %2"] = { fr = "Score final : A %1 · B %2", es = "Marcador final: A %1 · B %2", de = "Endstand: A %1 · B %2" },
    ["Forbidden clue with %1 of 6 expressions found: all or nothing!"] = { fr = "Indice interdit avec %1 expressions sur 6 trouvées : c'est tout ou rien !", es = "Pista prohibida con %1 de 6 expresiones acertadas: ¡todo o nada!", de = "Verbotener Hinweis bei %1 von 6 gefundenen Redewendungen: alles oder nichts!" },
    ["Hold the reader so only %1 sees it, then tap Ready."] = { fr = "Tenez la liseuse pour que seul(e) %1 la voie, puis touchez « Prêt ».", es = "Sostén el lector de modo que solo %1 lo vea y toca Listo.", de = "Haltet den Reader so, dass nur %1 ihn sieht, dann tippt auf Bereit." },
    ["Last word: %1 (lost)"] = { fr = "Mot précédent : %1 (perdu)", es = "Palabra anterior: %1 (perdida)", de = "Letztes Wort: %1 (verloren)" },
    ["Last word: %1 (team %2)"] = { fr = "Mot précédent : %1 (équipe %2)", es = "Palabra anterior: %1 (equipo %2)", de = "Letztes Wort: %1 (Team %2)" },
    ["Name %1 of %2"] = { fr = "Nom %1 sur %2", es = "Nombre %1 de %2", de = "Name %1 von %2" },
    ["Name %1 of %2 · %3 bricks at most."] = { fr = "Nom %1 sur %2 · %3 briques au plus.", es = "Nombre %1 de %2 · %3 ladrillos como mucho.", de = "Name %1 von %2 · höchstens %3 Steine." },
    ["No bid: team %1 plays in %2"] = { fr = "Pas d'annonce : l'équipe %1 joue en %2", es = "Sin puja: el equipo %1 juega en %2", de = "Kein Gebot: Team %1 spielt in %2" },
    ["Not solved"] = { fr = "Pas trouvée", es = "No resuelto", de = "Nicht gelöst" },
    ["One-word clues, each one costs a brick. Four rounds, then the winning team climbs the Great Pyramid: 6 expressions in 1 minute, all or nothing."] = { fr = "Des indices d'un seul mot, chacun coûte une brique. Quatre manches, puis l'équipe gagnante gravit la Grande Pyramide : 6 expressions en 1 minute, tout ou rien.", es = "Pistas de una sola palabra, cada una cuesta un ladrillo. Cuatro rondas y luego el equipo ganador sube la Gran Pirámide: 6 expresiones en 1 minuto, todo o nada.", de = "Hinweise aus einem Wort, jeder kostet einen Stein. Vier Runden, dann erklimmt das Siegerteam die Große Pyramide: 6 Redewendungen in 1 Minute, alles oder nichts." },
    ["Other name"] = { fr = "Autre nom", es = "Otro nombre", de = "Anderer Name" },
    ["Ping-pong"] = { fr = "Le ping-pong", es = "Ping-pong", de = "Ping-Pong" },
