    ["Sudden death: forbidden clue on “%1”, team %2 goes through."] = { fr = "Mort subite : indice interdit sur « %1 », l'équipe %2 est qualifiée.", es = "Muerte súbita: pista prohibida en «%1», pasa el equipo %2.", de = "Sudden Death: verbotener Hinweis bei „%1“, Team %2 kommt weiter." },
    ["Sudden death: team %1 found “%2”."] = { fr = "Mort subite : l'équipe %1 a trouvé « %2 ».", es = "Muerte súbita: el equipo %1 acertó «%2».", de = "Sudden Death: Team %1 hat „%2“ erraten." },
    ["Team %1"] = { fr = "Équipe %1", es = "Equipo %1", de = "Team %1" },
    ["Team %1 plays this name in %2 bricks at most. Bid fewer bricks to take it over: found, you score; missed, team %1 scores."] = { fr = "L'équipe %1 joue ce nom en %2 briques au plus. Annoncez moins de briques pour le prendre : trouvé, vous marquez ; manqué, l'équipe %1 marque.", es = "El equipo %1 juega este nombre en %2 ladrillos como mucho. Pujad menos ladrillos para quedároslo: si lo acertáis, puntuáis; si falláis, puntúa el equipo %1.", de = "Team %1 spielt diesen Namen in höchstens %2 Steinen. Bietet weniger Steine, um ihn zu übernehmen: erraten, ihr punktet; verfehlt, Team %1 punktet." },
