    ["“%1”: not found, team %2 scores %3."] = { fr = "« %1 » : pas trouvé, l'équipe %2 marque %3.", es = "«%1»: no acertado, el equipo %2 gana %3.", de = "„%1“: nicht erraten, Team %2 bekommt %3." },
